import time
from functools import wraps

def ttl_cache(seconds):
    def deco(fn):
        cache = {}
        @wraps(fn)
        def wrapper(*args):
            now = time.monotonic()
            if args in cache:
                value, stored = cache[args]
                if now - stored < seconds:
                    return value
            value = fn(*args)
            cache[args] = (value, now)
            return value
        return wrapper
    return deco

